# Interstate '76 Input mapping file
# MW5-STYLE LAPTOP LAYOUT applied to the ACTIVE input.map (2026-07-04)
# (KEYBOARD.MAP is IGNORED by this build; this is the file the engine reads.)
# W/S throttle(notched)  A/D steer  Enter fire  Tab cycle  F link  X reverse
# Space handbrake  I ignition  Q front-target  T nearest  Y next  U untarget
# R radar-range  K radar-cam  E glance-target  Arrows glance  P poetry
# 1-5 hardpoints 1-5  J hardpoint 1  L hardpoint 2  (header corrected 2026-10-03)
throttle {
   - joystick1  Down/Up
}
steer {
   - joystick1  Left/Right
}
throttle_up {
   + keyboard   W
	- Keyboard	Shift
	- Keyboard	Control
}
throttle_down {
   + keyboard   S
	- Keyboard	Shift
	- Keyboard	Control
}
steer_left {
   + keyboard   A
	- Keyboard	Shift
	- Keyboard	Control
}
steer_right {
   + keyboard   D
	- Keyboard	Shift
	- Keyboard	Control
}
shift_down {
   + keyboard   Comma
	- Keyboard	Shift
	- Keyboard	Control
}
shift_up {
   + keyboard   Period
	- Keyboard	Shift
	- Keyboard	Control
}
frontal_target {
   + keyboard   Q
	- Keyboard	Shift
	- Keyboard	Control
}
NEXT_TARGET {
   + keyboard   Y
	- Keyboard	Shift
	- Keyboard	Control
}
TARGET_NEAREST_ENEMY {
   + keyboard   T
	- Keyboard	Shift
	- Keyboard	Control
}
RESET_TARGET {
   + keyboard   U
	- Keyboard	Shift
	- Keyboard	Control
}
RADAR_RANGE_TOGGLE {
   + keyboard   R
	- Keyboard	Shift
	- Keyboard	Control
}
RADAR_CAMERA_TOGGLE {
   + keyboard   K
	- Keyboard	Shift
	- Keyboard	Control
}
start_engine {
   + keyboard   I
	- Keyboard	Shift
	- Keyboard	Control
}
SHOW_MAP {
   + keyboard   M
	- Keyboard	Shift
	- Keyboard	Control
}
SHOW_NOTEPAD {
   + keyboard   N
	- Keyboard	Shift
	- Keyboard	Control
}
TOGGLE_BINOCULARS {
   + keyboard   B
	- Keyboard	Shift
	- Keyboard	Control
}
HONK_HORN {
   + keyboard   G
	- Keyboard	Shift
	- Keyboard	Control
}
e_brake {
   + keyboard   Space
	- Keyboard	Shift
	- Keyboard	Control
}
toggle_lights {
   + keyboard   H
	- Keyboard	Shift
	- Keyboard	Control
}
# --- Arrow cluster: on Mac (Wine) AND over RDP the physical arrow keys arrive
# --- as NUMPAD "Grey" codes, so everything arrow-related is bound to Grey*Arrow.
# --- Bare arrow      = pilot glance (look out the side/rear windows).
# --- Shift + arrow   = tracking / overview camera (the old "numpad" functions).
# ---   Shift, NOT Ctrl: macOS reserves Ctrl+arrows for Mission Control / Spaces,
# ---   so Ctrl+arrow never reaches the game. Shift passes straight through Wine.
pilot_glance_up {
   + keyboard   GreyUpArrow
   - keyboard   Shift
}
pilot_glance_down {
   + keyboard   GreyDownArrow
   - keyboard   Shift
}
pilot_glance_left {
   + keyboard   GreyLeftArrow
   - keyboard   Shift
}
pilot_glance_right {
   + keyboard   GreyRightArrow
   - keyboard   Shift
}
track_pitch_minus {
   + keyboard   GreyUpArrow
   + keyboard   Shift
}
overview_z_minus {
   + keyboard   GreyUpArrow
   + keyboard   Shift
}
track_pitch_plus {
   + keyboard   GreyDownArrow
   + keyboard   Shift
}
overview_z_plus {
   + keyboard   GreyDownArrow
   + keyboard   Shift
}
track_yaw_minus {
   + keyboard   GreyLeftArrow
   + keyboard   Shift
}
overview_x_minus {
   + keyboard   GreyLeftArrow
   + keyboard   Shift
}
track_yaw_plus {
   + keyboard   GreyRightArrow
   + keyboard   Shift
}
overview_x_plus {
   + keyboard   GreyRightArrow
   + keyboard   Shift
}
pilot_glance_target {
   + keyboard   E
	- Keyboard	Shift
	- Keyboard	Control
}
weapon_fire {
   + keyboard   Enter
	- Keyboard	Shift
	- Keyboard	Control
}
weapon_cycle {
   + keyboard   Tab
	- Keyboard	Shift
	- Keyboard	Control
}
weapon_link {
   + keyboard   F
	- Keyboard	Shift
	- Keyboard	Control
}
hardpoint1_fire {
